import React, { useEffect, useState } from "react";
import API_BASE_URL from "../config";

const RentalOrders = () => {
  const [orders, setOrders] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/rentals/orders/${userId}`)
      .then((res) => res.json())
      .then((data) => setOrders(data));
  }, [userId]);

  return (
    <div>
      <h1>My Rental Orders</h1>
      {orders.length === 0 && <p>No rentals yet!</p>}
      {orders.map((order) => (
        <div key={order.id}>
          <h3>{order.title}</h3>
          <p>{order.description}</p>
          <p>${order.total_price} / {order.rental_duration}</p>
          {order.image && <img src={order.image} alt="rental" width="150" />}
          <p>Rented on: {new Date(order.created_at).toLocaleDateString()}</p>
        </div>
      ))}
    </div>
  );
};

export default RentalOrders;
